const app=document.querySelector('#app');
const state={tab:new URLSearchParams(location.search).get('tab')||'overview',invoices:[],transactions:[],allocations:[],suggestions:[],documents:[],imports:[],audit:[],settings:{},dashboard:{},bank:{configured:false,connections:[]},gmail:{configured:false,status:'disconnected',email:'mg.vitvaror@gmail.com'},filters:{customers:{q:'',status:'all',date:'all',page:1,size:10,sort:'due_at',asc:true},suppliers:{q:'',status:'all',date:'all',page:1,size:10,sort:'due_at',asc:true},bank:{q:'',status:'all',page:1,size:10}},menu:false,preview:null,loaded:null};
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',file:'<path d="M14 2H5v20h14V7z"/><path d="M14 2v6h5M8 12h8M8 16h6"/>',bank:'<path d="m2 8 10-6 10 6zM3 21h18M4 18h16M6 9v9M12 9v9M18 9v9"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 14v7h16v-7"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',settings:'<path d="m9 3 1-1h4l1 3 3 1 3 2-1 3v3l1 2-3 3-3-1-2 3H9l-1-3-3-1-2-2 1-3V9L3 7l3-3 3 1z"/><circle cx="12" cy="12" r="3"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 1-2 3M12 17h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 5 10 8L22 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 4v16M4 12h16"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',refresh:'<path d="M20 7V2l-4 4M4 17v5l4-4M20 7a9 9 0 0 0-15-2M4 17a9 9 0 0 0 15 2"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M7 10V7a5 5 0 0 1 10 0v3"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z"/><path d="m8 11 3 3 5-5"/>',logout:'<path d="M10 3H3v18h7M8 12h14m-5-5 5 5-5 5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18M7 15h3M14 15h3"/>',arrow:'<path d="M12 3v18m-6-6 6 6 6-6"/>',sort:'<path d="m8 8 4-4 4 4m-8 8 4 4 4-4"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',eye:'<path d="M2 12s4-8 10-8 10 8 10 8-4 8-10 8S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',undo:'<path d="M9 4 3 10l6 6M3 10h11a7 7 0 0 1 7 7v3"/>',filter:'<path d="M3 3h18l-7 8v8l-4 2V11z"/>',link:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6zM14 5l5 5"/>'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.file}</svg>`;
const gmailIcon=()=>'<svg class="gmail-icon" viewBox="0 0 32 26" aria-hidden="true"><path fill="#4285f4" d="M1 5 6 8v17H1z"/><path fill="#34a853" d="m26 8 5-3v20h-5z"/><path fill="#ea4335" d="M1 5c0-4 3-5 6-3l9 7 9-7c3-2 6-1 6 3l-15 12z"/><path fill="#c5221f" d="M1 5v6l5 4V8z"/><path fill="#fbbc04" d="M31 5v6l-5 4V8z"/></svg>';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('sv-SE',{style:'currency',currency:'SEK',maximumFractionDigits:Number(c)%100?2:0}).format((Number(c)||0)/100);
const iso=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dayOffset=n=>{const d=new Date(iso()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
const date=s=>s?String(s).slice(0,10):'–';
const datetime=s=>s?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',dateStyle:'short',timeStyle:'short'}).format(new Date(s.includes('T')?s:s.replace(' ','T')+'Z')):'Aldrig';
const company=()=>state.settings.company_name||'M.George Vitvaror AB';
const sum=(a,k='remaining_cents')=>a.reduce((s,i)=>s+(i[k]||0)*(i.kind==='credit'?-1:1),0);
const bankConnected=()=>state.bank.connections.some(c=>c.status==='connected');
const gmailConnected=()=>state.gmail.status==='connected';
const pendingDocs=()=>state.documents.filter(d=>!d.invoice_id&&d.status==='needs_review');
const byDirection=d=>state.invoices.filter(i=>i.direction===d);
const labelStatus={unreconciled:'Ej avstämd',unpaid:'Obetald',partial:'Delvis betald',paid:'Betald',overdue:'Förfallen',unmatched:'Ej matchad',suggested:'Förslag finns',matched:'Matchad',review:'Behöver granskning',excluded:'Undantagen',complete:'Klart',completed:'Klart',connected:'Ansluten',pending_account:'Välj företagskonto',disconnected:'Ej ansluten',not_connected:'Ej ansluten',renewal_required:'Behöver förnyas',error:'Fel vid hämtning',needs_review:'Behöver granskning',registered:'Registrerad'};
function badge(s,label){return `<span class="status ${esc(s==='completed'?'complete':s==='needs_review'?'review':s)}">${esc(label||labelStatus[s]||s)}</span>`;}
function bankActivationDetail(){const message=String(state.bank.activation?.message||'').trim();return message==='Banktjänsten behöver aktiveras av systemadministratören.'?'':message;}
function bankEnrichmentSummary(result){const count=Number(result.enriched)||0;return count?` · ${count} bankhändelse${count===1?'':'r'} kompletterad${count===1?'':'e'}`:'';}
function invoiceBadge(i){return badge(i.status)+(i.is_overdue&&i.status!=='overdue'&&i.status!=='paid'?'<small class="danger-text">Förfallodatum passerat</small>':'');}
function toast(message,error=false){const el=document.querySelector('#notice');el.textContent=message;el.className='notice'+(error?' error':'');el.hidden=false;clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>el.hidden=true,6500);}
async function api(path,method='GET',data){const r=await fetch('/api'+path,{method,credentials:'same-origin',headers:data!==undefined?{'Content-Type':'application/json'}:{},body:data!==undefined?JSON.stringify(data):undefined});const body=await r.json().catch(()=>({}));if(!r.ok){const e=Error(body.error||`Det gick inte att hämta uppgifterna (${r.status}).`);e.status=r.status;throw e;}return body;}
function handleError(e){if(e.status===401){showLogin('Din session har gått ut. Logga in igen.');return;}toast(e.message,true);}
function showLogin(message=''){++refreshVersion;closeModal();state.me={authenticated:false,login_required:true};app.innerHTML=`<main class="login-screen"><section class="login-brand"><a href="/" class="brand">${brand()}</a><h1>Fakturor och betalningar.<br><span>Samlat och säkert.</span></h1><p>Logga in i företagets arbetsyta för att granska fakturor och läsa bankhändelser.</p><div class="login-points"><span>${icon('check')}Kontroll över varje faktura</span><span>${icon('check')}Endast läsåtkomst till banken</span></div></section><section class="login-form-wrap"><form id="login-form" class="login-card"><span class="avatar">MG</span><h2>Logga in</h2><p>MG Fakturakoll · M.George Vitvaror AB</p><label>Lösenord<input type="password" name="password" required autocomplete="current-password" maxlength="1024"></label><p class="error-text" id="login-error" role="alert">${esc(message)}</p><button class="primary" type="submit">${icon('lock')}Logga in</button><small>Använd lösenordet till arbetsytan. Bankens inloggning sker separat hos banken.</small></form></section></main>`;app.querySelector('[name="password"]').focus();}
let refreshVersion=0;
async function refresh(){const version=++refreshVersion;const me=await api('/me');if(version!==refreshVersion)return;state.me=me;if(me.login_required&&!me.authenticated){showLogin();return false;}const results=await Promise.all([api('/dashboard'),api('/invoices'),api('/bank-transactions'),api('/allocations'),api('/bank/status'),api('/settings'),api('/gmail/status'),api('/suggestions'),api('/imports'),api('/documents')]);if(version!==refreshVersion)return;[state.dashboard,{items:state.invoices},{items:state.transactions},{items:state.allocations},state.bank,state.settings,state.gmail,{items:state.suggestions},{items:state.imports},{items:state.documents}]=results;state.loaded=new Date().toISOString();if(state.tab==='history')state.audit=(await api('/audit')).items;render();return true;}
function navigate(tab,filter){state.tab=tab;state.menu=false;if(filter&&state.filters[tab])Object.assign(state.filters[tab],{status:filter,page:1});history.pushState(null,'',tab==='overview'?'/':'/?tab='+encodeURIComponent(tab));closeModal();render();window.scrollTo({top:0});if(tab==='history')api('/audit').then(x=>{state.audit=x.items;render();}).catch(handleError);}
window.addEventListener('popstate',()=>{state.tab=new URLSearchParams(location.search).get('tab')||'overview';render();});
const nav=[['overview','Översikt','home'],['customers','Kundfakturor','file'],['suppliers','Leverantörsfakturor','file'],['bank','Bank','bank'],['import','Import','upload'],['settings','Inställningar','settings'],['help','Hjälp','help']];
const pages={overview:['MG Fakturakoll','Få koll på fakturor, betalningar och bankkopplingar'],customers:['Kundfakturor','Hantera dina kundfakturor och följ upp varje betalning.'],suppliers:['Leverantörsfakturor','Få koll på leverantörsfakturor och planera dina betalningar.'],bank:['Bankhändelser & matchning','Matcha bankhändelser mot dina fakturor och underlag.'],connections:['Koppla banken','Hämta bankhändelser säkert från ditt företagskonto.'],import:['Importera underlag','Samla fakturor och bankhändelser på ett ställe.'],settings:['Inställningar','Hantera ditt företag, dina anslutningar och aviseringar.'],help:['Hur kan vi hjälpa dig?','En enkel väg till bättre koll på fakturor och betalningar.'],history:['Händelsehistorik','Följ importer, ändringar och bekräftade matchningar.'],review:['Behöver granskning','Kontrollera underlag och godkänn rätt betalningsmatchningar.']};
function brand(){return `<span class="brand-logo" aria-hidden="true"><i></i><i></i><i></i></span><span><strong>MG Fakturakoll</strong><small>${esc(company())}</small></span>`;}
function render(){if(!pages[state.tab])state.tab='overview';const [title,desc]=pages[state.tab];document.title=title+' · MG Fakturakoll';const active=state.tab==='connections'?'bank':state.tab==='history'?'settings':state.tab==='review'?'overview':state.tab;app.innerHTML=`<div class="shell ${state.menu?'menu-open':''}">${state.menu?'<button class="menu-scrim" data-action="menu" aria-label="Stäng meny"></button>':''}<aside class="sidebar"><a href="/" class="brand" data-nav="overview">${brand()}</a><nav class="nav-group" aria-label="Huvudmeny">${nav.map(([key,text,i],idx)=>`${idx===5?'<div class="nav-spacer"></div>':''}<button class="nav-item ${key===active?'active':''}" data-nav="${key}" ${key===active?'aria-current="page"':''}>${icon(i)}${text}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace-tag">${icon('shield')}<span>${state.me?.login_required?'Företagets arbetsyta':'Din lokala arbetsyta'}<br>Fakturor och betalningar samlade</span></div>${state.me?.login_required?'<button class="text-button" data-action="logout">'+icon('logout')+'Logga ut</button>':''}<small>MG Fakturakoll · M.George</small></div></aside><div class="content"><header class="topbar"><button class="icon-button mobile-toggle" data-action="menu" aria-label="Öppna meny" aria-expanded="${state.menu}">${icon('menu')}</button><div class="heading-wrap"><h1>${title}</h1><p class="subtitle">${desc}</p></div><div class="top-actions"><button class="icon-button" data-action="refresh" aria-label="Uppdatera översikten" title="Uppdatera översikten">${icon('refresh')}</button><button class="icon-button notification-button ${notificationItems().length?'has-dot':''}" data-action="notifications" aria-label="Visa aviseringar">${icon('bell')}</button><button class="account-button" data-nav="settings" aria-label="Öppna företagsinställningar"><span class="avatar">MG</span><span class="account-name">${esc(company())}</span>${icon('down')}</button></div></header><main id="main">${tabContent()}<footer class="page-foot"><span>${icon('shield')} Endast läsåtkomst till banken · Inga betalningar utförs</span><span>${state.loaded?'Uppdaterad '+datetime(state.loaded):''}</span></footer></main></div></div>`;app.querySelector('.sidebar').inert=matchMedia('(max-width:760px)').matches&&!state.menu;}
function toggleMenu(){state.menu=!state.menu;const shell=app.querySelector('.shell');if(!shell)return;shell.classList.toggle('menu-open',state.menu);app.querySelector('.sidebar').inert=matchMedia('(max-width:760px)').matches&&!state.menu;const button=app.querySelector('.mobile-toggle');button?.setAttribute('aria-expanded',String(state.menu));let scrim=app.querySelector('.menu-scrim');if(state.menu&&!scrim){scrim=document.createElement('button');scrim.className='menu-scrim';scrim.dataset.action='menu';scrim.setAttribute('aria-label','Stäng meny');shell.prepend(scrim);}if(!state.menu)scrim?.remove();}
matchMedia('(max-width:760px)').addEventListener('change',()=>{const side=app.querySelector('.sidebar');if(side)side.inert=matchMedia('(max-width:760px)').matches&&!state.menu;});
function hero(title,text,note='Mindre manuellt arbete<br>Mer tid till din verksamhet'){return `<section class="hero"><div><h2>${title}</h2><p>${text}</p></div><div class="hero-art" aria-hidden="true"><div class="paper-art"><div class="sheet"></div><div class="sheet second"></div><div class="success-orb">${icon('check')}</div></div><div class="hero-note">${note}</div></div></section>`;}
function empty(i,title,text,action='',button=''){return `<div class="empty"><div class="orb">${icon(i)}</div><h3>${title}</h3><p>${text}</p>${action?`<button class="text-button" ${action}>${button} ${icon('chevron')}</button>`:''}</div>`;}
function stat(color,i,title,count,sub,attrs){return `<button class="stat ${color}" ${attrs}><span class="orb">${icon(i)}</span><div><span class="stat-label">${title}</span><strong class="stat-value">${count}</strong><span class="stat-sub">${sub}</span></div>${icon('chevron')}</button>`;}
function panel(title,content,attrs='',link='Visa alla'){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${attrs?`<button class="text-button" ${attrs}>${link}</button>`:''}</div>${content}</section>`;}
function connectionStrips(){const b=bankConnected(),g=gmailConnected(),bs=b?'connected':state.bank.connections[0]?.status||'not_connected',gs=state.gmail.status;return `<div class="connection-grid">${[[b,icon('bank'),'Bank',bs,b?'Bankhändelser hämtas från din bank.':bs==='renewal_required'?'Bankanslutningen behöver förnyas. Koppla igen för att fortsätta.':bs==='error'?'Hämtningen misslyckades. Öppna anslutningen och försök igen.':'Koppla din bank och hämta bankhändelser för avstämning.','data-nav="connections"',b?'Hantera':bs==='renewal_required'?'Koppla igen':bs==='error'?'Kontrollera':'Koppla nu'],[g,gmailIcon(),'Gmail',gs,g?'Senast hämtat: '+datetime(state.gmail.last_synced):gs==='renewal_required'?'Gmail-anslutningen behöver förnyas.':gs==='error'?'Hämtningen misslyckades. Du kan försöka igen.':'Hämta fakturaunderlag från din inkorg och skickade mejl.','data-action="gmail"',g?'Hämta nu':gs==='error'?'Försök igen':gs==='renewal_required'?'Koppla igen':'Koppla nu']].map(([ok,img,name,status,desc,attrs,btn])=>`<section class="connection-strip ${ok?'connected':''}"><div class="orb">${img}</div><div><h3>${name}: <span class="${ok?'success-text':'danger-text'}">${esc(labelStatus[status]||'Ej ansluten')}</span></h3><p>${desc}</p></div><button class="primary small" ${attrs}>${btn}</button></section>`).join('')}</div>`;}
function overview(){const d=state.dashboard;const onboard=!state.invoices.length||!bankConnected()||!gmailConnected();return hero('Välkommen till MG Fakturakoll!','Få en tydlig överblick över dina fakturor och betalningar.<br>Kom igång med stegen nedan – vi hjälper dig hela vägen.')+connectionStrips()+(onboard?`<section class="onboarding" aria-label="Kom igång">${[['Koppla banken','Hämta bankhändelser från ditt företagskonto.','bank','Koppla banken','data-nav="connections"','Säker läsåtkomst'],['Koppla mejlen','Samla fakturaunderlag direkt från din Gmail.','mail','Koppla Gmail','data-action="gmail"','Inkorgen och skickade mejl'],['Importera underlag','Ladda upp dina fakturor och bankfiler.','file','Importera nu','data-nav="import"','Granska innan registrering'],['Matcha betalningar','Kontrollera förslag och bekräfta rätt faktura.','check','Visa matchningar','data-nav="bank"','Du godkänner varje matchning']].map(([h,t,i,btn,attrs,sub],n)=>`<div class="step-card"><div class="step-top"><span class="step-number">${n+1}</span><h3>${h}</h3></div><p>${t}</p><span class="orb">${icon(i)}</span><button class="primary full ${n===3?'green':''}" ${attrs}>${btn}</button><small>${sub}</small></div>`).join('')}</section>`:'')+`<div class="stat-grid">${stat('','file','Kundfakturor med belopp kvar',d.customer_open_count||0,money(d.customer_open_cents),'data-nav="customers" data-filter="open"')}${stat('amber','file','Att betala · leverantörer',d.supplier_open_count||0,money(d.supplier_open_cents),'data-nav="suppliers" data-filter="open"')}${stat('green','bank','Nya bankhändelser',d.new_transactions_count||0,'senaste 7 dagarna','data-nav="bank"')}${stat('purple','clock','Behöver granskning',d.review_count||0,'fakturor, underlag och betalningar','data-nav="review"')}</div><div class="two-columns">${panel('Senaste kundfakturor',recentInvoices(byDirection('customer')),'data-nav="customers"')}${panel('Senaste bankhändelser',bankTable(state.transactions.slice(0,5),true),'data-nav="bank"')}</div>${byDirection('supplier').some(i=>i.remaining_cents>0)?panel('Kommande betalningar',upcomingRows(),'data-nav="suppliers"'):''}`;}
function recentInvoices(rows){rows=[...rows].sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,5);return rows.length?`<div class="table-scroll"><table><thead><tr><th>Fakturanr</th><th>Kund</th><th>Förfallodatum</th><th class="amount">Belopp</th><th>Status</th></tr></thead><tbody>${rows.map(i=>`<tr><td><button class="row-link" data-invoice="${i.id}">${esc(i.invoice_number)}</button></td><td>${esc(i.party)}</td><td class="nowrap">${date(i.due_at)}</td><td class="amount">${money(i.total_cents)}</td><td>${invoiceBadge(i)}</td></tr>`).join('')}</tbody></table></div>`:empty('file','Inga kundfakturor ännu','Lägg till din första faktura eller importera ett underlag.','data-action="new-invoice"','Lägg till kundfaktura');}
function invoiceSummary(direction){const a=byDirection(direction),open=a.filter(i=>i.remaining_cents>0),soon=open.filter(i=>i.due_at&&i.due_at>=iso()&&i.due_at<=dayOffset(7)),paid=a.filter(i=>i.status==='paid');return [stat(direction==='customer'?'red':'amber','file',direction==='customer'?'Kvar att få betalt':'Att betala',open.length,money(sum(open)),`data-nav="${state.tab}" data-filter="open"`),stat(direction==='customer'?'amber':'purple','clock','Förfaller inom 7 dagar',soon.length,money(sum(soon)),`data-nav="${state.tab}" data-filter="soon"`),stat('green','check','Betalda fakturor',paid.length,money(sum(paid,'total_cents')),`data-nav="${state.tab}" data-filter="paid"`)].join('');}
function filteredInvoices(){const f=state.filters[state.tab],direction=state.tab==='customers'?'customer':'supplier';return byDirection(direction).filter(i=>{const q=f.q.toLocaleLowerCase('sv-SE');if(q&&!`${i.invoice_number} ${i.party} ${i.reference}`.toLocaleLowerCase('sv-SE').includes(q))return false;if(f.status==='open'&&i.remaining_cents<=0)return false;if(f.status==='soon'&&!(i.remaining_cents>0&&i.due_at>=iso()&&i.due_at<=dayOffset(7)))return false;if(f.status==='overdue'&&!i.is_overdue)return false;if(!['all','open','soon','overdue'].includes(f.status)&&i.status!==f.status)return false;if(f.date==='month'&&!i.due_at.startsWith(iso().slice(0,7)))return false;if(f.date==='week'&&!(i.due_at>=iso()&&i.due_at<=dayOffset(7)))return false;return true;}).sort((a,b)=>{const x=a[f.sort],y=b[f.sort];return (typeof x==='number'?x-y:String(x||'').localeCompare(String(y||''),'sv-SE'))*(f.asc?1:-1);});}
function filters(){const f=state.filters[state.tab];return `<div class="filters"><div class="search-field">${icon('search')}<input id="invoice-search" data-search="${state.tab}" aria-label="Sök fakturor" value="${esc(f.q)}" placeholder="Sök på fakturanr, ${state.tab==='customers'?'kund':'leverantör'} eller referens…"></div><label>Status<select data-filter-select="status">${[['all','Alla statusar'],['open','Belopp kvar'],['unreconciled','Ej avstämda'],['unpaid','Obetalda'],['partial','Delvis betalda'],['paid','Betalda'],['overdue','Förfallodatum passerat'],['soon','Förfaller inom 7 dagar']].map(([v,t])=>`<option value="${v}" ${f.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="date-filter">Förfallodatum<select data-filter-select="date"><option value="all">Alla datum</option><option value="month" ${f.date==='month'?'selected':''}>Denna månad</option><option value="week" ${f.date==='week'?'selected':''}>Kommande 7 dagar</option></select></label>${state.tab==='customers'?`<button class="primary" data-action="new-invoice">${icon('plus')} Lägg till faktura</button>`:''}</div>`;}
function invoicePage(){const customer=state.tab==='customers';return (customer?`<div class="stat-grid three">${invoiceSummary('customer')}</div>`:hero('Håll koll på dina leverantörsfakturor!','Se fakturor, förfallodatum och betalningsstatus.<br>Planera dina betalningar och följ upp det som återstår.','Bättre kontroll<br>Starkare likviditet')+`<div class="supplier-summary">${invoiceSummary('supplier')}<div class="action-stack"><button class="primary" data-action="new-invoice">${icon('plus')} Lägg till faktura</button><button class="outline" data-action="upload-invoice">${icon('upload')} Importera PDF / bild</button></div></div>`)+filters()+`<div class="${customer?'':'supplier-layout'}"><section><div id="invoice-results">${invoiceResults()}</div></section>${customer?'':`<aside class="panel side-panel"><h2>Kommande betalningar</h2><p class="muted">Prioriterade efter förfallodatum.</p>${upcomingRows()}<div class="info-note">${icon('calendar')}<div><strong>Planera dina betalningar</strong>Kontrollera förfallodatum och saldo i banken. Du genomför betalningen hos din bank.</div></div></aside>`}</div>`;}
function invoiceResults(){const rows=filteredInvoices(),f=state.filters[state.tab];const max=Math.max(1,Math.ceil(rows.length/f.size));f.page=Math.min(f.page,max);const part=rows.slice((f.page-1)*f.size,f.page*f.size);return `<div class="list-tools"><p class="muted">${rows.length?`Visar ${(f.page-1)*f.size+1}–${Math.min(f.page*f.size,rows.length)} av ${rows.length} fakturor`:'Inga fakturor att visa'}</p><div class="button-row"><button class="soft-button small" data-action="upload-invoice">${icon('upload')} Importera</button><button class="soft-button small" data-action="export-invoices">${icon('download')} Exportera</button></div></div><div class="panel">${part.length?`<div class="table-scroll"><table><thead><tr>${[['invoice_number','Fakturanr'],['party',state.tab==='customers'?'Kund':'Leverantör'],['issued_at','Fakturadatum'],['due_at','Förfallodatum'],['total_cents','Belopp'],['paid_cents','Betalt'],['remaining_cents','Kvar']].map(([key,t])=>`<th ${key.endsWith('cents')?'class="amount"':''}><button class="sort-button" data-sort="${key}" aria-label="Sortera efter ${t}">${t}${icon('sort')}</button></th>`).join('')}<th>Status</th><th>Åtgärd</th></tr></thead><tbody>${part.map(i=>`<tr><td class="nowrap"><button class="row-link" data-invoice="${i.id}">${esc(i.invoice_number)}</button>${i.kind==='credit'?'<small>Kreditfaktura</small>':''}</td><td>${esc(i.party)}</td><td class="nowrap">${date(i.issued_at)}</td><td class="nowrap">${date(i.due_at)}</td><td class="amount">${i.kind==='credit'?'−':''}${money(i.total_cents)}</td><td class="amount">${money(i.paid_cents)}</td><td class="amount">${money(i.remaining_cents)}</td><td>${invoiceBadge(i)}</td><td><button class="row-action" data-invoice="${i.id}" aria-label="Öppna faktura ${esc(i.invoice_number)}">${icon('more')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('file',f.q||f.status!=='all'?'Inga fakturor matchar sökningen':state.tab==='customers'?'Inga kundfakturor ännu':'Inga leverantörsfakturor ännu',f.q||f.status!=='all'?'Prova ett annat sökord eller välj alla statusar.':'Lägg till en faktura eller ladda upp ett originalunderlag.','data-action="new-invoice"','Lägg till faktura')}${pagination(rows.length,f)}</div>`;}
function pagination(total,f){const n=Math.max(1,Math.ceil(total/f.size));const numbers=[...new Set([1,f.page-1,f.page,f.page+1,n])].filter(x=>x>0&&x<=n).sort((a,b)=>a-b);return `<div class="pagination"><label class="page-size">Visa<select data-page-size>${[10,25,50].map(v=>`<option value="${v}" ${f.size===v?'selected':''}>${v}</option>`).join('')}</select>per sida</label><div class="pages"><button data-page="${f.page-1}" ${f.page<=1?'disabled':''} aria-label="Föregående sida">${icon('chevron','rotate-left')}</button>${numbers.map(n=>`<button data-page="${n}" ${f.page===n?'class="active" aria-current="page"':''}>${n}</button>`).join('')}<button data-page="${f.page+1}" ${f.page>=n?'disabled':''} aria-label="Nästa sida">${icon('chevron')}</button></div></div>`;}
function upcomingRows(){const rows=byDirection('supplier').filter(i=>i.remaining_cents>0&&i.kind!=='credit').slice().sort((a,b)=>(a.due_at||'9999').localeCompare(b.due_at||'9999')).slice(0,4);return rows.length?rows.map(i=>`<div class="upcoming-row"><span class="party-avatar">${esc(i.party.slice(0,2).toLocaleUpperCase('sv-SE'))}</span><div>${badge(i.is_overdue?'overdue':'unreconciled',i.due_at?date(i.due_at):'Datum saknas')}<button class="row-link" data-invoice="${i.id}"><strong>${esc(i.party)}</strong></button><small>${esc(i.invoice_number)}</small></div><b>${money(i.remaining_cents)}</b><button class="icon-button" data-invoice="${i.id}" aria-label="Öppna faktura ${esc(i.invoice_number)}">${icon('chevron')}</button></div>`).join(''):empty('calendar','Inga kommande betalningar','Här visas leverantörsfakturor med kvarstående belopp.');}
function bankTable(rows,compact=false,preview=false){return rows.length?`<div class="table-scroll"><table><thead><tr><th>Datum</th>${compact?'':'<th>Typ</th>'}<th>Beskrivning</th><th class="amount">Belopp</th>${compact?'':'<th>Referens / förslag</th>'}<th>Status</th>${preview?'':'<th></th>'}</tr></thead><tbody>${rows.map(t=>{const s=state.suggestions.find(s=>s.transaction_id===t.id),i=s&&state.invoices.find(i=>i.id===s.invoice_id);return `<tr><td class="nowrap">${date(t.booked_at)}</td>${compact?'':`<td class="nowrap ${t.amount_cents>0?'positive':''}">${t.amount_cents>0?'↓ Inbetalning':'↑ Utbetalning'}</td>`}<td><strong>${esc(t.payer||'Betalare saknas')}</strong><small>${esc(t.description||'')}</small>${t.is_aggregate?'<small class="bank-review-warning">Betalardetaljer saknas – importera betalningsspecifikation.</small>':t.review_reason?'<small>'+esc(t.review_reason)+'</small>':''}</td><td class="amount ${t.amount_cents>0?'positive':'negative'}">${money(t.amount_cents)}</td>${compact?'':`<td>${esc(t.reference||i?.invoice_number||'–')}${i?`<small>${esc(i.party)}</small>`:''}</td>`}<td>${badge(preview?t.is_aggregate?'review':'unmatched':t.status,t.status==='partial'?'Delvis fördelad':undefined)}</td>${preview?'':`<td><button class="${compact?'icon-button':'row-action'}" data-transaction="${t.id}" aria-label="Granska bankhändelse ${esc(t.payer||t.booked_at)}">${icon('chevron')}</button></td>`}</tr>`;}).join('')}</tbody></table></div>`:empty('bank','Inga bankhändelser ännu','Koppla din bank eller importera en bankfil för att börja stämma av.','data-nav="connections"','Koppla banken');}
function bankPage(){const d=state.dashboard;return `<div class="stat-grid three">${stat('green','bank','Nya bankhändelser',d.new_transactions_count||0,'senaste 7 dagarna','data-bank-filter="all"')}${stat('','check','Matchade',d.matched_count||0,'bekräftade bankhändelser','data-bank-filter="matched"')}${stat('purple','clock','Att granska',d.unmatched_count||0,'bankhändelser med belopp kvar','data-bank-filter="review"')}</div><div class="bank-layout"><section class="panel"><div class="panel-head"><div><h2>Bankhändelser</h2><p class="muted">Granska och matcha mot rätt faktura.</p></div><div class="button-row"><button class="outline small" data-nav="connections">${icon('bank')} Bankanslutning</button><button class="primary small" data-action="bank-file">${icon('upload')} Importera</button></div></div><div class="toggle-pills">${[['all','Alla händelser'],['review','Att granska'],['suggested','Förslag finns'],['matched','Matchade'],['excluded','Undantagna']].map(([k,t])=>`<button class="${state.filters.bank.status===k?'active':''}" data-bank-filter="${k}">${t}</button>`).join('')}</div><div id="bank-results">${bankResults()}</div><div class="section-space"><button class="text-button" data-action="new-transaction">${icon('plus')} Registrera med bankunderlag</button></div></section><aside class="panel"><h2>Så granskar du</h2><p class="muted">Matcha betalningar i tre enkla steg.</p><div class="match-guide">${[['Gå igenom förslag','Vi jämför referens, belopp och betalare.'],['Granska och välj','Kontrollera underlaget och välj rätt faktura.'],['Bekräfta matchning','När du godkänner uppdateras fakturans betalningsstatus.']].map(([h,t],n)=>`<div class="guide-item"><span class="step-number">${n+1}</span><div><h3>${h}</h3><p>${t}</p></div></div>`).join('')}</div><button class="primary full" data-action="review-next">${icon('check')} Granska förslag</button><div class="info-note">${icon('info')}<div><strong>Nyttigt att veta</strong>Du kan dela en betalning mellan flera fakturor. Alla matchningar sparas i historiken och kan rättas.</div></div></aside></div>`;}
function bankResults(){const f=state.filters.bank,rows=state.transactions.filter(t=>f.status==='all'||f.status==='review'&&t.available_cents>0&&!t.excluded||t.status===f.status);f.page=Math.min(f.page,Math.max(1,Math.ceil(rows.length/f.size)));return bankTable(rows.slice((f.page-1)*f.size,f.page*f.size))+pagination(rows.length,f);}
function connectionPage(){const ok=bankConnected(),pending=state.bank.connections.some(c=>c.status==='pending_account'),status=ok?'connected':pending?'pending_account':state.bank.connections[0]?.status||'not_connected';return hero('Koppla banken','Hämta bokförda bankhändelser från ditt företagskonto och granska betalningarna.','Enkelt att följa upp<br>Tryggt att ha kontroll')+`<div class="connection-layout"><section class="panel bank-connect"><ol class="bank-steps" aria-label="Så ansluter du banken">${[['Välj bank','Swedbank är förvald.'],['Godkänn hos Swedbank','Identifiera dig och godkänn läsåtkomst.'],['Välj företagskonto','Hämta betalningar och börja stämma av.']].map(([h,t],n)=>`<li class="bank-step ${n===0||n===2&&pending?'current':''}"><span class="step-number" aria-hidden="true">${n+1}</span><h3>${h}</h3><p>${t}</p></li>`).join('')}</ol><div class="bank-choice"><span class="swedbank-logo" aria-hidden="true">S</span><span>Swedbank<small>Företagskonto · Endast läsåtkomst</small></span>${icon('lock')}</div><p class="bank-connection-status">Status: ${badge(status)}</p>${!state.bank.configured?`<div class="info-note warning bank-activation" role="status">${icon('info')}<div><strong>Banktjänsten behöver aktiveras av systemadministratören.</strong>${bankActivationDetail()?`<p>${esc(bankActivationDetail())}</p>`:''}</div></div>`:''}${!ok&&!pending?`<button class="primary full" data-action="connect-bank">${icon('lock')}Koppla banken${icon('chevron')}</button><p class="caption bank-consent-copy">Du skickas till bankens säkra inloggning för att godkänna att MG Fakturakoll får läsa dina bankhändelser.</p>`:''}${String(state.bank.environment||'').toUpperCase()==='SANDBOX'?'<p class="document-warning section-space">Testmiljö – här visas endast testkonton och testhändelser.</p>':''}${state.bank.connections.map(connectionCard).join('')}<div class="divider">eller</div><button class="outline full" data-action="bank-file">${icon('file')}Importera bankfil istället${icon('chevron')}</button><p class="caption">CSV, camt.053 eller camt.054. Du förhandsgranskar och bekräftar importen.</p></section><aside class="panel guide-panel"><h2>Så fungerar det</h2><div class="guide-list">${[['Välj bank','Swedbank är förvald för företagets bankhändelser.'],['Godkänn hos banken','Du identifierar dig direkt hos Swedbank, med BankID när banken erbjuder det.'],['Välj konto och granska','De senaste 30 dagarnas bokförda händelser hämtas om medgivandet tillåter det. Du godkänner varje fakturamatchning.']].map(([h,t],n)=>`<div class="guide-item"><span class="step-number">${n+1}</span><div><h3>${h}</h3><p>${t}</p></div></div>`).join('')}</div><div class="info-note green">${icon('shield')}<div><strong>Din bank, ditt godkännande</strong>Vi sparar inga BankID-koder eller banklösenord. Åtkomsten används för att läsa konton och bankhändelser.</div></div><div class="info-note">${icon('file')}<div><strong>Betalardetaljer saknas?</strong>En Bankgiroinsättning kan omfatta flera kundbetalningar. Importera betalningsspecifikation eller camt.054 för att granska varje betalning.</div></div></aside></div>`;}
function connectionCard(c){const accounts=c.accounts||[],pending=c.status==='pending_account',selected=accounts.find(a=>a.uid===c.selected_account_uid),canSync=!!selected&&!pending&&c.status!=='renewal_required',id=esc(c.id);return `<section class="connection-account" aria-label="${esc(c.bank_name||'Swedbank')} bankanslutning"><div class="panel-head"><strong>${esc(c.bank_name||'Swedbank')}</strong>${badge(c.status)}</div>${pending?`<p class="muted">Banken har bekräftat medgivandet. Välj företagets konto för att slutföra anslutningen.</p><label for="acc-${id}" class="section-space">Företagets konto<select id="acc-${id}"><option value="">Välj konto…</option>${accounts.map(a=>`<option value="${esc(a.uid)}">${esc(a.name||'Bankkonto')} · ${esc(a.account_hint||'Kontonummer saknas')} · ${esc(a.currency||'SEK')}</option>`).join('')}</select></label><button class="primary full section-space" data-select-bank-account="${id}" ${!accounts.length?'disabled':''}>${icon('check')}Anslut valt konto</button><p class="caption">Vi försöker hämta de senaste 30 dagarnas bokförda bankhändelser. Du granskar sedan betalningarna.</p>`:`<dl class="bank-account-facts"><div><dt>Valt konto</dt><dd>${selected?`${esc(selected.name||'Bankkonto')} · ${esc(selected.account_hint||'Kontonummer saknas')} · ${esc(selected.currency||'SEK')}`:'Konto behöver väljas efter nytt medgivande'}</dd></div><div><dt>Senast uppdaterad</dt><dd>${datetime(c.last_synced)}</dd></div><div><dt>Medgivandet gäller till</dt><dd>${c.valid_until?datetime(c.valid_until):'Giltighetstid saknas – förnya anslutningen'}</dd></div></dl>${c.status==='renewal_required'?'<p class="document-warning">Medgivandet har gått ut eller återkallats. Förnya anslutningen hos Swedbank för att hämta fler händelser.</p>':c.status==='error'?'<p class="document-warning">Bankhändelser kunde inte hämtas. Försök uppdatera igen eller förnya anslutningen.</p>':''}${canSync?`<details class="bank-date-range"><summary>Välj datumintervall</summary><div class="dates"><label for="from-${id}">Från<input type="date" id="from-${id}" value="${dayOffset(-29)}" max="${iso()}"></label><label for="to-${id}">Till<input type="date" id="to-${id}" value="${iso()}" max="${iso()}"></label></div></details>`:''}<div class="button-row section-space"><button class="primary small" data-sync="${id}" ${canSync?'':'disabled'}>${icon('refresh')}Uppdatera bankhändelser</button><button class="outline small" data-renew-bank="${id}">${icon('link')}Förnya anslutningen</button></div>`}<div class="button-row section-space"><button class="text-button small" data-disconnect-bank="${id}">Koppla från banken</button>${canSync?'<button class="text-button small" data-nav="bank">Visa bankhändelser '+icon('chevron')+'</button>':''}</div></section>`;}
function importPage(){return hero('Samla dina underlag. Få koll på betalningarna.','Hämta fakturabilagor från Gmail eller ladda upp dina filer.<br>Granska fakturauppgifterna och stäm av mot bankens betalningar.')+`<section class="import-options"><article class="import-card"><div class="import-card-head"><span class="orb">${gmailIcon()}</span><div><h2>${gmailConnected()?'Gmail är ansluten':'Koppla Gmail'}</h2><p>Hämta fakturabilagor från företagets inkorg och skickade mejl.</p></div></div><div class="import-card-bottom">${features(['Läser inkorgen och skickade mejl','Säker anslutning via Google','Originalbilagor sparas för granskning'])}<button class="primary full" data-action="gmail">${gmailIcon()}${gmailConnected()?'Hämta fakturaunderlag':'Koppla Gmail'}</button><p class="caption">${esc(state.gmail.email||'mg.vitvaror@gmail.com')}</p></div></article><article class="import-card blue import-drop" data-drop="invoice"><div class="import-card-head"><span class="orb">${icon('file')}</span><div><h2>Ladda upp fakturor</h2><p>Välj PDF-filer eller bilder. Originalet sparas och du fyller i fakturauppgifterna.</p></div></div><div class="import-card-bottom">${features(['Stöd för flera filer','Originalet följer med fakturan','Du granskar före registrering'])}<button class="primary full" data-action="upload-invoice">${icon('upload')}Välj PDF-filer / bilder</button><p class="caption">Dra och släpp här · högst 15 MB per fil</p></div></article><article class="import-card green import-drop" data-drop="bank"><div class="import-card-head"><span class="orb">${icon('bank')}</span><div><h2>Importera bankfil</h2><p>Ladda upp kontoutdrag eller betalningsspecifikation och kontrollera händelserna.</p></div></div><div class="import-card-bottom">${features(['CSV, camt.053 och camt.054','Förhandsgranskning före import','Dublettkontroll och matchningsförslag'])}<button class="primary full" data-action="bank-file">${icon('upload')}Välj bankfil</button><p class="caption">CSV eller XML · högst 1 000 händelser</p></div></article></section>${state.preview?previewPanel():''}${state.documents.some(d=>!d.invoice_id)?panel('Underlag att registrera',pendingDocs().length?documentsTable(pendingDocs()):empty('check','Inga underlag väntar','Alla underlag har hanterats.'),'data-action="dismissed-documents"','Visa undantagna'):''}${panel('Senaste importer',importTable(state.imports.slice(0,10)),'data-action="import-history"','Visa alla importer')}`;}
function features(items){return `<ul class="feature-list">${items.map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul>`;}
function documentsTable(rows){return `<div class="table-scroll"><table><thead><tr><th>Originalunderlag</th><th>Källa</th><th>Inkommet</th><th>Status</th><th>Åtgärd</th></tr></thead><tbody>${rows.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.subject||'')}</small></td><td>${d.source==='gmail'?'Gmail':'Uppladdning'}</td><td class="nowrap">${date(d.created_at)}</td><td>${badge('review','Granska uppgifter')}</td><td><div class="button-row"><button class="text-button" data-document="${d.id}" aria-label="Registrera faktura från ${esc(d.name)}">Registrera faktura ${icon('chevron')}</button><button class="icon-button" data-dismiss-document="${d.id}" aria-label="Undanta underlag ${esc(d.name)}">${icon('close')}</button></div></td></tr>`).join('')}</tbody></table></div>`;}
function importTable(rows){return rows.length?`<div class="table-scroll"><table><thead><tr><th>Datum</th><th>Källa</th><th>Fil / underlag</th><th>Antal</th><th>Status</th><th>Resultat</th><th></th></tr></thead><tbody>${rows.map(j=>`<tr><td class="nowrap">${datetime(j.created_at)}</td><td>${esc(sourceLabel(j.source))}</td><td>${esc(j.name||sourceLabel(j.source))}</td><td>${j.found}</td><td>${badge(j.status)}</td><td>${j.imported} nya · ${j.duplicate} dubbletter${j.error?`<small class="danger-text">${esc(j.error)}</small>`:''}</td><td><button class="text-button" data-import="${j.id}">Visa detaljer ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('upload','Ingen importhistorik ännu','Dina importer och deras resultat visas här när du har lagt till underlag.');}
const sourceLabel=s=>({bank_file:'Bankfil',document:'PDF / bild',gmail:'Gmail',manual:'Manuell registrering',enablebanking:'Bankanslutning'}[s]||s);
function previewPanel(){const p=state.preview;return `<section class="panel" id="import-preview"><div class="preview-toolbar"><div><h2>Förhandsgranska bankfilen</h2><p class="muted">${esc(p.name)} · ${p.count} händelser · ${p.review||0} behöver kontroll</p>${p.account_label?'<p class="muted">Konto: '+esc(p.account_label)+'</p>':''}</div><button class="icon-button" data-action="cancel-preview" aria-label="Avbryt förhandsgranskning">${icon('close')}</button></div>${(p.warnings||[]).map(w=>`<div class="document-warning">${esc(w)}</div>`).join('')}${bankTable(p.items,false,true)}<div class="button-row section-space"><button class="primary" data-action="confirm-import">${icon('check')}Bekräfta import av ${p.count} händelser</button><button class="outline" data-action="cancel-preview">Avbryt</button></div><p class="muted section-space">Inga bankhändelser sparas innan du bekräftar. Redan importerade händelser hoppas över.</p></section>`;}
function settingsPage(){const s=state.settings;return `<div class="settings-layout"><section><form id="settings-form" class="panel settings-section"><h2>Företagsuppgifter</h2><p class="muted">Uppgifterna används i din arbetsyta och i påminnelseutkast.</p><div class="form-grid">${[['company_name','Företagsnamn','text'],['organization_number','Organisationsnummer','text'],['email','E-postadress','email'],['phone','Telefon','tel'],['bankgiro','Bankgiro','text'],['address','Adress','text']].map(([key,t,type])=>`<label>${t}<input name="${key}" type="${type}" value="${esc(s[key]||'')}" ${key==='company_name'?'required':''} maxlength="${key==='address'?500:240}"></label>`).join('')}</div><h3 class="section-space">Automatisk hämtning</h3><p class="muted">Anslutna konton uppdateras medan systemets server är igång.</p><label>Hämta nya underlag<select name="sync_interval_minutes">${[[0,'Endast när jag väljer att uppdatera'],[15,'Var 15:e minut'],[30,'Var 30:e minut'],[60,'Varje timme'],[240,'Var fjärde timme'],[1440,'En gång om dagen']].map(([v,t])=>`<option value="${v}" ${Number(s.sync_interval_minutes)===v?'selected':''}>${t}</option>`).join('')}</select></label><h3 class="section-space">Aviseringar i arbetsytan</h3><div class="section-space"><label class="check-label"><input type="checkbox" name="notifications_due" ${s.notifications_due?'checked':''}>Visa fakturor som förfaller snart och passerade förfallodatum</label><label class="check-label section-space"><input type="checkbox" name="notifications_review" ${s.notifications_review?'checked':''}>Visa underlag och betalningar som behöver granskning</label></div><button type="submit" class="primary">${icon('check')}Spara inställningar</button><div id="settings-error" role="alert" class="error-text"></div></form><section class="panel settings-section"><h2>Data och historik</h2><p class="muted">Exportera dina register eller följ tidigare ändringar.</p><div class="button-row"><button class="outline" data-action="export-all">${icon('download')}Exportera register</button><button class="outline" data-nav="history">${icon('clock')}Visa händelsehistorik</button></div><details><summary>Avancerade inställningar</summary><p>Originalfiler sparas separat i systemets databas och kan laddas ned vid respektive faktura eller import. Registerexporten innehåller metadata, betalningar och granskningshistorik. Säkerhetskopiera hela databasen för att även bevara originalfiler och anslutningar.</p><p>${state.me?.login_required?'Företagets arbetsyta kräver inloggning.':'Den här installationen används lokalt för ett företag och öppnas utan lösenord.'} Anslutningsnycklar förvaras på servern.</p><p>Senaste automatiska hämtning: ${datetime(s.scheduler?.last_run)}${s.scheduler?.last_error?'<br>'+esc(s.scheduler.last_error):''}</p></details></section></section><aside><section class="panel"><h2>Anslutningar</h2><div class="setting-row"><span class="orb">${icon('bank')}</span><div><strong>Swedbank</strong>${badge(bankConnected()?'connected':state.bank.connections[0]?.status||'not_connected')}</div><button class="text-button" data-nav="connections">Hantera</button></div><div class="setting-row"><span class="orb">${gmailIcon()}</span><div><strong>Gmail</strong><small>${esc(state.gmail.email)}</small><div>${badge(state.gmail.status)}</div></div><button class="text-button" data-action="gmail-settings">Hantera</button></div></section><section class="panel"><h2>Påminnelser</h2><p class="muted section-space">Du kan skapa ett utkast på en kundfaktura med kvarstående belopp. Kontrollera alltid betalningsstatus innan du skickar det.</p><div class="info-note">${icon('info')}<div>Inga betalningspåminnelser skickas automatiskt.</div></div></section><section class="panel"><h2>${state.me?.login_required?'Företagets arbetsyta':'Lokal arbetsyta'}</h2><div class="setting-row"><span class="avatar">MG</span><div><strong>${state.me?.login_required?'Inloggad':'Direkt åtkomst'}</strong><small>${state.me?.login_required?'Skyddad företagsåtkomst':'Ingen inloggning behövs'}</small></div></div><p class="muted">${state.me?.login_required?'Du är inloggad i företagets arbetsyta.':'Appen öppnas direkt på den här datorn.'} Google och banken har egna godkännandeflöden när du ansluter dem.</p>${state.me?.login_required?'<button class="outline section-space" data-action="logout">'+icon('logout')+'Logga ut</button>':''}</section></aside></div>`;}
function reviewPage(){const tx=state.transactions.filter(t=>!t.excluded&&t.available_cents>0),inv=state.invoices.filter(i=>i.status==='unreconciled'),docs=pendingDocs();return hero('Lite hjälp från dig. Bättre koll på varje betalning.','Kontrollera originalunderlaget och bekräfta det som stämmer.<br>Betalningsstatus ändras när du godkänner en matchning.')+panel(`Betalningar att granska (${tx.length})`,bankTable(tx))+panel(`Fakturor att stämma av (${inv.length})`,inv.length?`<div class="table-scroll"><table><thead><tr><th>Fakturanr</th><th>Kund / leverantör</th><th>Belopp</th><th>Status</th><th></th></tr></thead><tbody>${inv.map(i=>`<tr><td>${esc(i.invoice_number)}</td><td>${esc(i.party)}</td><td>${money(i.remaining_cents)}</td><td>${invoiceBadge(i)}</td><td><button class="text-button" data-invoice="${i.id}">Granska faktura ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('check','Alla registrerade fakturor är avstämda','Nya fakturor som behöver betalningskontroll visas här.'))+panel(`Originalunderlag att registrera (${docs.length})`,docs.length?documentsTable(docs):empty('check','Inga underlag väntar','Uppladdade och hämtade originalunderlag visas här tills de har registrerats.'));}
function helpPage(){return hero('Vi hjälper dig att komma igång','Börja med dina fakturor och bankhändelser.<br>Granska sedan matchningsförslagen, ett i taget.')+`<div class="help-grid">${[['bank','Koppla banken','Godkänn läsåtkomst hos Swedbank eller börja med att importera en bankfil.','connections','Gå till bankanslutning'],['upload','Lägg till underlag','Hämta bilagor från Gmail eller ladda upp en faktura som PDF eller bild.','import','Importera underlag'],['file','Följ upp fakturor','Sök efter kunder, se kvarstående belopp och öppna fakturan för att kontrollera originalet.','customers','Visa kundfakturor'],['check','Matcha betalningar','Kontrollera OCR, belopp och betalare. När du godkänner uppdateras fakturans status.','bank','Granska matchningar']].map(([i,h,t,tab,btn])=>`<section class="panel"><span class="orb">${icon(i)}</span><h2 class="section-space">${h}</h2><p>${t}</p><button class="text-button section-space" data-nav="${tab}">${btn}${icon('chevron')}</button></section>`).join('')}</div><section class="panel faq"><h2>Vanliga frågor</h2>${[['Varför står det ”Ej avstämd”?','Det betyder att fakturan är registrerad men att betalningsunderlaget ännu inte har kontrollerats. Det är inte ett besked om att kunden inte har betalat.'],['Hur fungerar delbetalningar?','Välj fakturan när du granskar bankhändelsen och ange den del av betalningen som hör till fakturan. Återstående belopp visas automatiskt. Du kan fördela resten på andra fakturor.'],['Vad gör jag med en samlad Bankgiroinsättning?','Importera bankens betalningsspecifikation, exempelvis camt.054, så att enskilda betalare och referenser framgår. En osäker totalsumma får inte matchas direkt mot en faktura.'],['Kan jag rätta en matchning?','Öppna fakturan eller bankhändelsen och välj att ångra matchningen. Ändringen sparas i historiken. Kontrollera sedan rätt underlag och matcha igen.'],['Läser systemet fakturauppgifter automatiskt?','Gmail-integrationen hämtar möjliga fakturabilagor. I den här versionen registrerar du uppgifterna manuellt med originalet som underlag. Automatisk tolkning av skannade fakturor är ännu inte aktiverad.'],['Varför går det inte att koppla banken eller Gmail?','Systemansvarig måste aktivera respektive integration en gång. Därefter använder du bankens eller Googles säkra godkännandeflöde. Lösenord till banken och Gmail ska aldrig skrivas in i MG Fakturakoll.'],['Hur säkerhetskopierar jag uppgifterna?','Register kan exporteras i Inställningar. För en fullständig återställning behöver systemansvarig även säkerhetskopiera databasen, originalfilerna och krypteringsnyckeln på en säker plats.']].map(([h,t])=>`<details><summary>${h}</summary><p>${t}</p></details>`).join('')}</section>`;}
function historyPage(){const labels={invoice_created:'Faktura registrerad',invoice_updated:'Fakturauppgifter ändrade',invoice_reconciled:'Betalningsunderlag kontrollerat',manual_match:'Betalningsmatchning godkänd',undo_match:'Matchning återförd',bank_import:'Bankhändelser importerade',document_uploaded:'Originalunderlag sparat',settings_updated:'Inställningar sparade',transaction_excluded:'Bankhändelse undantagen',transaction_restored:'Bankhändelse återställd',gmail_connected:'Gmail ansluten',gmail_disconnected:'Gmail frånkopplad',bank_connected:'Bank ansluten',bank_disconnected:'Bank frånkopplad',data_exported:'Register exporterade',aggregate_replaced:'Samlingspost ersatt av betalningsspecifikation'};return panel('Senaste händelser',state.audit.length?`<div class="history-timeline">${state.audit.map(a=>`<article class="history-event">${icon('clock')}<div><strong>${esc(labels[a.action]||a.action)}</strong>${datetime(a.created_at)}<details><summary>Visa spårbar information</summary><code>${esc(a.details)}</code></details></div></article>`).join('')}</div>`:empty('clock','Ingen händelsehistorik ännu','Registreringar, importer och godkända matchningar sparas här.'));}
function tabContent(){return ({overview,customers:invoicePage,suppliers:invoicePage,bank:bankPage,connections:connectionPage,import:importPage,settings:settingsPage,help:helpPage,review:reviewPage,history:historyPage}[state.tab]||overview)();}

let focusBeforeModal=null;
function closeModal(){app.inert=false;const root=document.querySelector('#modal-layer');root.innerHTML='';document.body.classList.remove('modal-open');if(focusBeforeModal?.isConnected)focusBeforeModal.focus();focusBeforeModal=null;}
function modal(title,content,submit,onSubmit,wide=false){focusBeforeModal=document.activeElement;const root=document.querySelector('#modal-layer');root.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><form id="dialog-form"><header class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" type="button" data-close aria-label="Stäng dialog">${icon('close')}</button></header><div class="modal-body">${content}<div class="modal-error" id="dialog-error" role="alert" hidden></div></div><footer class="modal-foot"><button class="outline" type="button" data-close>${submit?'Avbryt':'Stäng'}</button>${submit?`<button class="primary" type="submit">${esc(submit)}</button>`:''}</footer></form></section></div>`;document.body.classList.add('modal-open');app.inert=true;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);root.querySelector('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal();};root.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!onSubmit)return;const button=e.submitter;if(button)button.disabled=true;const error=root.querySelector('#dialog-error');error.hidden=true;try{const message=await onSubmit(new FormData(e.currentTarget));closeModal();await refresh();toast(typeof message==='string'?message:'Sparat.');}catch(err){if(error.isConnected){error.textContent=err.message;error.hidden=false;}else handleError(err);}finally{if(button?.isConnected)button.disabled=false;}};root.querySelector('[data-close]').focus();}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();if(state.menu)toggleMenu();}if(e.key==='Tab'){const dialog=document.querySelector('.modal');if(!dialog)return;const focusable=[...dialog.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary')].filter(x=>x.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
function invoiceDialog(doc=null,existing=null){const i=existing||{},supplier=doc?.direction==='supplier'||!doc?.direction&&state.tab==='suppliers';modal(existing?'Redigera fakturauppgifter':doc?'Registrera faktura från underlag':'Lägg till faktura',`${doc?`<a class="document-row" href="/api/documents/${doc.id}" target="_blank" rel="noopener">${icon('file')}<span>${esc(doc.name)}</span>${icon('download')}</a><p class="document-warning">Läs originalet och kontrollera fakturanummer, belopp och förfallodatum. Uppgifterna nedan behöver fyllas i och bekräftas av dig.</p>`:''}<div class="form-grid">${existing?'':`<label>Typ<select name="direction"><option value="customer" ${!supplier?'selected':''}>Kundfaktura</option><option value="supplier" ${supplier?'selected':''}>Leverantörsfaktura</option></select></label><label>Underlag<select name="kind"><option value="invoice">Faktura</option><option value="credit">Kreditfaktura</option></select></label><label>Fakturanummer<input name="invoice_number" required maxlength="80" placeholder="Ange fakturanummer"></label>`}<label>${existing?i.direction==='customer'?'Kund':'Leverantör':'Kund / leverantör'}<input name="party" required maxlength="240" value="${esc(i.party||doc?.party||'')}"></label><label>E-post (valfritt)<input name="email" type="email" maxlength="240" value="${esc(i.email||doc?.email||'')}"></label><label>Fakturadatum<input name="issued_at" type="date" required value="${i.issued_at||iso()}"></label><label>Förfallodatum<input name="due_at" type="date" required value="${i.due_at||''}"></label>${existing?'':`<label>Belopp inklusive moms (kr)<input name="amount" type="number" step="0.01" min="0.01" required placeholder="0,00"></label><label>Moms (kr, valfritt)<input name="vat" type="number" step="0.01" min="0" placeholder="0,00"></label>`}<label>OCR / betalningsreferens<input name="reference" maxlength="120" value="${esc(i.reference||'')}"></label><label>Bankgiro (valfritt)<input name="bankgiro" maxlength="80" value="${esc(i.bankgiro||'')}"></label><label class="span-two">Anteckning<textarea name="note" rows="2" maxlength="1500">${esc(i.note||'')}</textarea></label></div>${!existing?`<div class="info-note">${icon('info')}<div>Fakturan registreras som <strong>Ej avstämd</strong> tills betalningsunderlaget har kontrollerats. En kreditfaktura registreras med positivt belopp och minskar det öppna nettobeloppet.</div></div>`:''}`,existing?'Spara ändringar':'Registrera faktura',async f=>{const data={party:f.get('party'),email:f.get('email'),issued_at:f.get('issued_at'),due_at:f.get('due_at'),reference:f.get('reference'),bankgiro:f.get('bankgiro'),note:f.get('note')};if(existing)await api('/invoices','PATCH',{id:i.id,...data});else await api('/invoices','POST',{...data,direction:f.get('direction'),kind:f.get('kind'),invoice_number:f.get('invoice_number'),total_cents:Math.round(Number(f.get('amount'))*100),...(f.get('vat')!==''?{vat_cents:Math.round(Number(f.get('vat'))*100)}:{}),...(doc?{document_id:doc.id}:{})});},true);}
async function invoiceDetail(id){try{const {invoice:i,allocations,documents}=await api('/invoices/'+encodeURIComponent(id));modal('Faktura '+i.invoice_number,`<div class="detail-amount"><div><small>${esc(i.party)}${i.kind==='credit'?' · Kreditfaktura':''}</small><strong>${money(i.total_cents)}</strong></div>${invoiceBadge(i)}</div><dl class="detail-grid">${[['Typ',i.direction==='customer'?'Kundfaktura':'Leverantörsfaktura'],['Fakturadatum',date(i.issued_at)],['Förfallodatum',date(i.due_at)],['OCR / referens',i.reference||'–'],['Betalt / avstämt',money(i.paid_cents)],['Kvar att stämma av',money(i.remaining_cents)],['Bankgiro',i.bankgiro||'–'],['E-post',i.email||'–']].map(([t,v])=>`<div><dt>${t}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${i.note?`<div class="info-note">${icon('info')}<div>${esc(i.note)}</div></div>`:''}<div><h3>Originalunderlag</h3>${documents.length?documents.map(d=>`<a class="document-row section-space" href="/api/documents/${d.id}" target="_blank" rel="noopener">${icon('file')}<span>${esc(d.name)}</span>${icon('download')}</a>`).join(''):'<p class="muted">Inget original har bifogats.</p>'}<button class="text-button section-space" data-attach="${i.id}">${icon('upload')}Bifoga original</button></div><div><h3>Betalningshistorik</h3>${allocations.length?allocations.map(a=>`<div class="payment-row section-space"><span class="orb">${icon('check')}</span><div><strong>${money(a.amount_cents)} · ${date(a.transaction?.booked_at)}</strong>${esc(a.transaction?.payer||'Bankbetalning')} · Bekräftad ${datetime(a.confirmed_at)}</div><button type="button" class="icon-button" data-undo="${a.id}" aria-label="Ångra matchning">${icon('undo')}</button></div>`).join(''):'<p class="muted">Inga verifierade betalningar registrerade.</p>'}</div><div class="button-row"><button type="button" class="outline small" data-edit-invoice="${i.id}">${icon('edit')}Redigera</button>${i.remaining_cents>0?`<button type="button" class="outline small" data-reconcile="${i.id}">${icon('check')}Kontrollera betalningsstatus</button>`:''}${i.direction==='customer'&&i.remaining_cents>0&&i.kind!=='credit'?`<button type="button" class="outline small" data-reminder="${i.id}">${icon('mail')}Påminnelseutkast</button>`:''}</div>`,null,null,true);}catch(e){handleError(e);}}
function reconcileDialog(id){const i=state.invoices.find(x=>x.id===id);modal('Kontrollera betalningsstatus',`<p>Faktura <strong>${esc(i.invoice_number)}</strong> till ${esc(i.party)} har ${money(i.remaining_cents)} kvar att stämma av.</p><div class="info-note warning">${icon('info')}<div>Om du hittar en betalning ska den matchas under Bank. Denna kontroll bekräftar att du har granskat tillgängligt underlag utan att hitta fler betalningar.</div></div><label>Vilket underlag har du kontrollerat?<textarea name="reconciliation_note" required maxlength="1500" rows="3" placeholder="Ange konto, datumintervall och vad du har kontrollerat."></textarea></label><label class="check-label"><input name="confirm" type="checkbox" required>Jag har kontrollerat bankunderlaget och bekräftar att inga ytterligare betalningar finns i det granskade materialet.</label>`,'Bekräfta kontroll',f=>api('/invoices','PATCH',{id,reconciled:true,confirm:f.get('confirm')==='on',reconciliation_note:f.get('reconciliation_note')}));}
function reminderDialog(id){const i=state.invoices.find(x=>x.id===id);const text=`Hej!\n\nVi vill vänligen påminna om faktura ${i.invoice_number} på ${money(i.total_cents)}, med förfallodatum ${date(i.due_at)}. Enligt det underlag vi har stämt av återstår ${money(i.remaining_cents)}.\n\nOm du redan har betalat får du gärna återkomma med betalningsdatum och referens så att vi kan kontrollera betalningen.\n\nTack på förhand!\n${company()}${state.settings.email?'\n'+state.settings.email:''}`;modal('Utkast till betalningspåminnelse',`<div class="info-note warning">${icon('info')}<div>Kontrollera aktuella betalningar innan du använder utkastet. ${i.status==='unreconciled'?'Fakturan är ännu inte avstämd.':''} Ingenting skickas från systemet.</div></div><label>Mottagare<input value="${esc(i.email)}" readonly></label><label>Ämne<input value="${esc('Påminnelse – faktura '+i.invoice_number)}" readonly></label><label>Text<textarea rows="11" id="reminder-text">${esc(text)}</textarea></label><button class="outline" type="button" data-action="download-reminder">${icon('download')}Ladda ned utkast</button>`,null,null);}
function bankDialog(){modal('Registrera bankhändelse',`<div class="info-note">${icon('info')}<div>Registrera endast en bokförd händelse från ett bankunderlag. Positivt belopp är en inbetalning, negativt belopp en utbetalning.</div></div><label>Konto<input name="account" required value="Swedbank" maxlength="120"></label><div class="dates"><label>Bokföringsdatum<input name="booked_at" type="date" value="${iso()}" required></label><label>Belopp (kr)<input name="amount" type="number" step="0.01" required placeholder="0,00"></label></div><label>Betalare / mottagare<input name="payer" maxlength="240"></label><label>OCR / fakturareferens<input name="reference" maxlength="240"></label><label>Bankens transaktionsreferens<input name="bank_reference" maxlength="240"></label><label>Beskrivning<input name="description" maxlength="500"></label>`,'Registrera bankhändelse',f=>api('/bank-transactions','POST',{account:f.get('account'),booked_at:f.get('booked_at'),amount_cents:Math.round(Number(f.get('amount'))*100),payer:f.get('payer'),reference:f.get('reference'),bank_reference:f.get('bank_reference'),description:f.get('description')}));}
function transactionDialog(id){const t=state.transactions.find(x=>x.id===id);if(!t)return;const options=state.invoices.filter(i=>!state.allocations.some(a=>a.transaction_id===id&&a.invoice_id===i.id)&&i.remaining_cents>0&&Math.sign(t.amount_cents)===(i.direction==='customer'?1:-1)*(i.kind==='credit'?-1:1)).sort((a,b)=>Number(state.suggestions.some(s=>s.transaction_id===id&&s.invoice_id===b.id))-Number(state.suggestions.some(s=>s.transaction_id===id&&s.invoice_id===a.id)));const allocations=state.allocations.filter(a=>a.transaction_id===id);const canMatch=!t.excluded&&!t.is_aggregate&&t.available_cents>0&&options.length&&!!(t.payer||t.reference);modal('Granska bankhändelse',`<div class="detail-amount"><div><small>${esc(t.payer||'Betalare saknas')} · ${date(t.booked_at)}</small><strong>${money(t.amount_cents)}</strong></div>${badge(t.status,t.status==='partial'?'Delvis fördelad':undefined)}</div><dl class="detail-grid">${[['Konto',t.account],['Beskrivning',t.description||'–'],['Kundens OCR / fakturareferens',t.reference||'–'],['Bankens transaktionsreferens',t.bank_reference||'–'],...(t.bankgiro?[['Företagets Bankgiro',t.bankgiro]]:[]),['Fördelat belopp',money(t.allocated_cents)],['Kvar att fördela',money(t.available_cents)]].map(([h,v])=>`<div><dt>${h}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${t.import_id&&state.imports.some(j=>j.id===t.import_id&&j.has_original)?`<a class="text-button" href="/api/imports/${t.import_id}/original">${icon('download')}Ladda ned originalfil</a>`:''}${t.review_reason||t.is_aggregate?`<div class="info-note warning">${icon('info')}<div>${esc(t.is_aggregate?'Betalardetaljer saknas – importera betalningsspecifikation.':t.review_reason)}</div></div>`:''}${t.excluded?`<p class="muted">Undantagen: ${esc(t.exclusion_reason)}</p>`:''}${allocations.length?`<div><h3>Bekräftade matchningar</h3>${allocations.map(a=>{const i=state.invoices.find(i=>i.id===a.invoice_id);return `<div class="payment-row section-space"><div><strong>${esc(i?.invoice_number)} · ${esc(i?.party)}</strong>${money(a.amount_cents)} · ${datetime(a.confirmed_at)}</div><button type="button" class="icon-button" data-undo="${a.id}" aria-label="Ångra matchning">${icon('undo')}</button></div>`;}).join('')}</div>`:''}${canMatch?`<h3>Välj faktura</h3><div class="match-options">${options.map((i,n)=>{const s=state.suggestions.find(s=>s.transaction_id===id&&s.invoice_id===i.id);return `<label class="match-option"><input type="radio" name="invoice_id" value="${i.id}" ${n===0?'checked':''} required><span><strong>${esc(i.invoice_number)} · ${esc(i.party)}</strong><small>${money(i.remaining_cents)} kvar · Förfaller ${date(i.due_at)}</small>${s?badge('suggested',s.reason):''}</span></label>`;}).join('')}</div><label>Belopp att matcha (kr)<input name="amount" id="match-amount" type="number" min="0.01" step="0.01" max="${(t.available_cents/100).toFixed(2)}" value="${(Math.min(t.available_cents,options[0].remaining_cents)/100).toFixed(2)}" required></label><label class="check-label"><input type="checkbox" name="confirm" required>Jag har kontrollerat referens, betalare och belopp mot originalunderlaget och godkänner matchningen.</label><p class="muted">Vill du fördela betalningen på flera fakturor? Matcha ett delbelopp och öppna sedan händelsen igen för resten.</p>`:t.available_cents>0&&!t.excluded&&!t.is_aggregate?`<div class="info-note">${icon('info')}<div>${options.length?'Betalaruppgifter eller referens saknas. Importera kompletterande bankunderlag för att matcha säkert.':'Ingen öppen faktura med rätt betalningsriktning finns att välja.'}</div></div>`:''}<div class="button-row">${!allocations.length&&!t.excluded?`<button type="button" class="text-button" data-exclude="${id}">Inte fakturarelaterad / undanta</button>`:''}${t.excluded&&!t.is_aggregate?`<button type="button" class="text-button" data-restore="${id}">Återställ för granskning</button>`:''}</div>`,canMatch?'Godkänn matchning':null,canMatch?f=>api('/allocations','POST',{transaction_id:id,invoice_id:f.get('invoice_id'),amount_cents:Math.round(Number(f.get('amount'))*100),confirm:f.get('confirm')==='on'}):null,true);const form=document.querySelector('#dialog-form');form.addEventListener('change',e=>{if(e.target.name==='invoice_id'){const i=options.find(i=>i.id===e.target.value);form.querySelector('#match-amount').value=(Math.min(t.available_cents,i.remaining_cents)/100).toFixed(2);}});}
function excludeDialog(id){modal('Undanta från fakturamatchning',`<p>Använd detta för exempelvis avgifter och inköp som inte hör till en registrerad faktura. Originaluppgifterna finns kvar i registret.</p><label>Orsak<textarea name="reason" rows="3" maxlength="500" required placeholder="Beskriv varför händelsen ska undantas."></textarea></label>`,'Undanta bankhändelse',f=>api('/bank-transactions','PATCH',{id,excluded:true,reason:f.get('reason')}));}
function undoDialog(id){modal('Ångra betalningsmatchning',`<p>Den verifierade kopplingen mellan fakturan och bankhändelsen tas bort. Beloppen räknas om och ändringen sparas i historiken.</p><label class="check-label"><input type="checkbox" name="confirm" required>Jag vill rätta matchningen och kontrollera underlaget igen.</label>`,'Ångra matchning',()=>api('/allocations','DELETE',{id}));}
function activationDialog(service){const bank=service==='bank';modal(bank?'Aktivera bankanslutningen':'Aktivera Gmail-anslutningen',`<div class="info-note">${icon('info')}<div><strong>${bank?'Banktjänsten behöver aktiveras av systemadministratören.':'En engångsinställning behövs'}</strong>${bank?esc(bankActivationDetail()||'Kontakta systemadministratören för att aktivera banktjänsten och kontrollera att Swedbank Företag är tillgängligt.'):'Systemansvarig behöver aktivera Google-inloggning för företaget. Därefter väljer du mg.vitvaror@gmail.com och godkänner läsåtkomst hos Google.'}</div></div><p>${bank?'Du kan börja direkt genom att importera en bankfil.':'Du kan börja direkt genom att ladda upp en faktura som PDF eller bild.'}</p><button type="button" class="primary" data-action="${bank?'bank-file':'upload-invoice'}">${icon('upload')}${bank?'Importera bankfil istället':'Ladda upp faktura'}</button>${bank?'':'<p class="muted">Systemadministratören hittar aktiveringsguiden i projektets dokumentation.</p>'}`,null,null);}
async function connectBank(renewId){if(!state.bank.configured)return activationDialog('bank');try{const r=await api('/bank/connect','POST',renewId?{renew_connection_id:renewId}:{});const target=new URL(r.url);if(target.protocol!=='https:'||target.hostname!=='auth.enablebanking.com'||target.username||target.password)throw Error('Banktjänsten returnerade en ogiltig inloggningsadress.');location.assign(target.href);}catch(e){try{state.bank=await api('/bank/status');render();}catch{}throw e;}}
async function selectBankAccount(id){const account=document.getElementById('acc-'+id)?.value;if(!account)throw Error('Välj företagets konto innan du fortsätter.');try{const r=await api('/bank/accounts','POST',{connection_id:id,account_uid:account});if(!await refresh())return;const connection=state.bank.connections.find(c=>c.id===id);if(connection?.status==='renewal_required'){toast('Medgivandet behöver förnyas. Förnya anslutningen hos Swedbank för att hämta bankhändelser.',true);return;}if(connection?.status!=='connected'){toast(r.initial_sync_error||'Anslutningen kunde inte bekräftas. Kontrollera bankstatus och försök igen.',true);return;}if(r.initial_sync_error){toast('Kontot är anslutet, men bankhändelser kunde inte hämtas. '+r.initial_sync_error,true);return;}toast(`Kontot är anslutet. ${r.imported||0} nya bankhändelser · ${r.duplicate||0} redan importerade${bankEnrichmentSummary(r)}.`);}catch(e){try{state.bank=await api('/bank/status');render();}catch{}throw e;}}
async function gmailAction(){if(!state.gmail.configured)return activationDialog('gmail');if(gmailConnected()||state.gmail.status==='error'&&state.gmail.connection){const r=await api('/gmail/sync','POST',{});await refresh();toast(`${r.imported} nya underlag · ${r.duplicate} dubbletter · ${r.skipped||0} överhoppade.${r.truncated?' Fler underlag finns att hämta.':''}`);navigate('import');}else{const r=await api('/gmail/connect','POST',{});location.assign(r.url);}}
function gmailSettings(){modal('Gmail-anslutning',`<div class="setting-row"><span class="orb">${gmailIcon()}</span><div><strong>${esc(state.gmail.email)}</strong>${badge(state.gmail.status)}</div></div><p class="muted">Senast hämtat: ${datetime(state.gmail.last_synced)}</p><p class="muted">Hämtar möjliga fakturabilagor från inkorgen och skickade mejl. Varje underlag granskas innan det registreras som faktura.</p><div class="button-row"><button class="primary" type="button" data-action="gmail">${gmailConnected()?'Hämta fakturaunderlag':state.gmail.status==='error'?'Försök hämta igen':'Koppla Gmail'}</button>${state.gmail.connection?'<button class="outline" type="button" data-action="disconnect-gmail">Koppla från</button>':''}</div>`,null,null);}
function disconnectDialog(type,id){modal(type==='bank'?'Koppla från banken':'Koppla från Gmail',`<p>Åtkomsten återkallas och nya uppgifter slutar hämtas. Dina redan registrerade fakturor, originalunderlag och bankhändelser finns kvar.</p><label class="check-label"><input type="checkbox" required name="confirm">Jag vill återkalla anslutningen.</label>`,'Koppla från',()=>api(type==='bank'?'/bank/connections':'/gmail/connection','DELETE',type==='bank'?{id}:{}));}
async function syncBank(id){const connection=state.bank.connections.find(c=>c.id===id);if(!connection?.selected_account_uid)throw Error('Välj först företagets bankkonto.');const from=document.getElementById('from-'+id)?.value,to=document.getElementById('to-'+id)?.value;if(from&&to&&from>to)throw Error('Fråndatum får inte ligga efter tilldatum.');try{const r=await api('/bank/sync','POST',{connection_id:id,...(from?{date_from:from}:{}),...(to?{date_to:to}:{})});await refresh();toast(`${r.imported} nya bankhändelser · ${r.duplicate} redan importerade${bankEnrichmentSummary(r)}.`);}catch(e){try{state.bank=await api('/bank/status');render();}catch{}throw e;}}
function filePicker(accept,multiple,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.multiple=multiple;input.className='file-input';input.oncancel=()=>input.remove();input.onchange=()=>{const files=[...input.files];input.remove();if(files.length)callback(files).catch(handleError);};document.body.append(input);input.click();}
async function base64(file){if(file.size>15_000_000)throw Error('Välj en fil som är mindre än 15 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary);}
async function uploadInvoices(files,invoice_id=null){const results=[],errors=[];for(const f of files){try{const b64=await base64(f);results.push(await api('/documents','POST',{name:f.name,content_base64:b64,...(invoice_id?{invoice_id}:{})}));}catch(e){errors.push(f.name+': '+e.message);}}await refresh();if(errors.length)toast(errors.join(' · '),true);if(invoice_id){if(results.length){if(!errors.length)toast('Originalunderlaget har bifogats.');return invoiceDetail(invoice_id);}return;}navigate('import');if(results.length===1&&!results[0].invoice_id&&!errors.length)invoiceDialog(results[0]);else if(results.length&&!errors.length)toast(`${results.filter(r=>!r.duplicate).length} nya underlag · ${results.filter(r=>r.duplicate).length} dubbletter.`);}
function uploadInvoice(invoiceId=null){closeModal();filePicker('.pdf,.png,.jpg,.jpeg,.webp,application/pdf,image/png,image/jpeg,image/webp',!invoiceId,files=>uploadInvoices(files,invoiceId));}
function bankFilePicker(){closeModal();filePicker('.csv,.xml,text/csv,application/xml,text/xml',false,files=>previewFile(files[0]));}
async function previewFile(file){const data={name:file.name,content_base64:await base64(file)},choices=state.bank.connections.flatMap(c=>{const account=(c.accounts||[]).find(a=>a.uid===c.selected_account_uid);return account?[{connection_id:c.id,account_uid:account.uid,label:`${c.bank_name||'Swedbank'} · ${account.name||'Bankkonto'} · ${account.account_hint||'Kontonummer saknas'} · ${account.currency||'SEK'}`}]:[];});modal('Importera bankfil',`<p>${esc(file.name)}</p><label>Vilket konto gäller bankfilen?<select name="connection_id" required>${choices.length?'<option value="" disabled selected>Välj konto…</option>':''}${choices.map(c=>`<option value="${esc(c.connection_id)}">${esc(c.label)}</option>`).join('')}<option value="manual" ${choices.length?'':'selected'}>Separat filkonto – ange ett kontonamn nedan</option></select></label><label>Kontonamn vid separat import<input name="account" maxlength="120" placeholder="Till exempel Swedbank företagskonto" ${choices.length?'disabled':'required'}></label><p class="muted">Välj det sparade bankkontot för att komplettera dess Bankgiroinsättningar med betalningsspecifikationer. För ett separat filkonto använder du samma kontonamn vid varje import.</p>`,'Förhandsgranska',async f=>{const target=f.get('connection_id'),choice=choices.find(c=>c.connection_id===target),account=String(f.get('account')||'').trim();if(target!=='manual'&&!choice)throw Error('Välj kontot som bankfilen gäller.');if(target==='manual'&&!account)throw Error('Ange ett kontonamn för det separata filkontot.');const identity=choice?{connection_id:choice.connection_id,account_uid:choice.account_uid}:{account},p=await api('/import/preview','POST',{...data,...identity});state.preview={...p,...data,...identity,account_label:choice?.label||account};state.tab='import';history.pushState(null,'','/?tab=import');return 'Förhandsgranskningen är klar. Bekräfta för att importera.';});const form=document.querySelector('#dialog-form'),select=form.querySelector('[name="connection_id"]'),alias=form.querySelector('[name="account"]');select.addEventListener('change',()=>{const manual=select.value==='manual';alias.disabled=!manual;alias.required=manual;if(manual)alias.focus();});}
async function commitImport(){const p=state.preview;if(!p)return;const identity=p.connection_id?{connection_id:p.connection_id,account_uid:p.account_uid}:{account:p.account},r=await api('/import/commit','POST',{name:p.name,...identity,content_base64:p.content_base64,confirm:true});state.preview=null;await refresh();toast(`${r.imported} bankhändelser importerade · ${r.duplicate} dubbletter överhoppade${bankEnrichmentSummary(r)}.`);navigate('bank');}
function dismissDocument(id){modal('Undanta underlag',`<p>Underlaget finns kvar och kan återställas, men visas inte längre som en faktura att registrera.</p><label>Orsak<textarea name="reason" rows="3" maxlength="500" required placeholder="Exempelvis orderbekräftelse eller redan hanterat underlag."></textarea></label>`,'Undanta underlag',f=>api('/documents','PATCH',{id,status:'dismissed',reason:f.get('reason')}));}
function dismissedDocuments(){const rows=state.documents.filter(d=>!d.invoice_id&&d.status==='dismissed');modal('Undantagna underlag',rows.length?rows.map(d=>`<div class="document-row">${icon('file')}<span>${esc(d.name)}</span><a class="icon-button" href="/api/documents/${d.id}" aria-label="Ladda ned ${esc(d.name)}">${icon('download')}</a><button type="button" class="text-button" data-restore-document="${d.id}">Återställ</button></div>`).join(''):empty('file','Inga undantagna underlag','Här kan du återställa ett underlag som tidigare undantagits.'),null,null);}
function importDetail(id){const j=state.imports.find(j=>j.id===id);if(!j)return;modal('Importresultat',`<div class="detail-amount"><div><small>${esc(sourceLabel(j.source))} · ${datetime(j.created_at)}</small><h3>${esc(j.name||'Hämtade underlag')}</h3></div>${badge(j.status)}</div><dl class="detail-grid">${[['Hittade poster',j.found],['Importerade',j.imported],['Dubbletter överhoppade',j.duplicate],['För granskning vid import',j.review]].map(([t,v])=>`<div><dt>${t}</dt><dd>${v}</dd></div>`).join('')}</dl>${j.error?`<div class="document-warning">${esc(j.error)}</div>`:''}${j.has_original?`<a class="outline" href="/api/imports/${j.id}/original">${icon('download')}Ladda ned bankens originalfil</a>`:''}<p class="muted">Bankhändelser granskas under Bank. Fakturaunderlag registreras under Import.</p>`,null,null);}
function notificationItems(){const items=[];if(state.settings.notifications_due){const overdue=state.invoices.filter(i=>i.is_overdue&&i.kind!=='credit');if(overdue.length)items.push({title:`${overdue.length} fakturor har passerat förfallodatum`,text:'Kontrollera betalningsunderlaget och följ upp kvarstående belopp.',tab:'review'});const soon=byDirection('supplier').filter(i=>i.remaining_cents>0&&i.due_at>=iso()&&i.due_at<=dayOffset(7)&&i.kind!=='credit');if(soon.length)items.push({title:`${soon.length} leverantörsfakturor förfaller snart`,text:'Se kommande betalningar och planera ditt saldo.',tab:'suppliers'});}if(state.settings.notifications_review&&state.dashboard.review_count)items.push({title:`${state.dashboard.review_count} poster behöver granskning`,text:'Kontrollera nya underlag och matchningsförslag.',tab:'review'});if(state.bank.connections.some(c=>c.status!=='connected'))items.push({title:'Bankanslutningen behöver kontrolleras',text:'Kontrollera medgivandet och koppla igen vid behov.',tab:'connections'});if(['error','renewal_required'].includes(state.gmail.status))items.push({title:'Gmail-anslutningen behöver kontrolleras',text:'Öppna dina inställningar och koppla Gmail igen.',tab:'settings'});return items;}
function notifications(){const items=notificationItems();modal('Aviseringar',items.length?items.map(n=>`<div class="notification-row"><strong>${esc(n.title)}</strong><small>${esc(n.text)}</small><div><button type="button" class="text-button section-space" data-nav="${n.tab}">Visa detaljer${icon('chevron')}</button></div></div>`).join(''):empty('check','Allt är lugnt just nu','Inga nya aviseringar utifrån dina inställningar och registrerade uppgifter.'),null,null);}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportInvoices(){const rows=filteredInvoices();const cell=x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const table=[['Fakturanummer','Typ','Kund / leverantör','Fakturadatum','Förfallodatum','Belopp SEK','Betalt SEK','Kvar SEK','Status','OCR / referens'],...rows.map(i=>[i.invoice_number,i.kind==='credit'?'Kreditfaktura':'Faktura',i.party,i.issued_at,i.due_at,(i.total_cents/100).toFixed(2).replace('.',','),(i.paid_cents/100).toFixed(2).replace('.',','),(i.remaining_cents/100).toFixed(2).replace('.',','),labelStatus[i.status],i.reference])];download(`mg-${state.tab==='customers'?'kundfakturor':'leverantorsfakturor'}-${iso()}.csv`,'\uFEFF'+table.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast(`${rows.length} fakturor exporterade.`);}
async function exportAll(){const data=await api('/export');download('mg-fakturakoll-'+iso()+'.json',JSON.stringify(data,null,2),'application/json');toast('Registret har exporterats. Originalfiler laddas ned separat.');}
function rerenderResults(){const id=state.tab==='bank'?'bank-results':'invoice-results';const root=document.getElementById(id);if(root)root.innerHTML=state.tab==='bank'?bankResults():invoiceResults();}
app.addEventListener('submit',async e=>{if(e.target.id!=='login-form')return;e.preventDefault();const form=e.target,button=e.submitter,error=form.querySelector('#login-error');button.disabled=true;error.textContent='';try{await api('/login','POST',{password:new FormData(form).get('password')});form.reset();await refresh();}catch(err){if(error.isConnected)error.textContent=err.message;}finally{form.reset();if(button.isConnected)button.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled||!(b.dataset.selectBankAccount||b.dataset.renewBank||b.dataset.action==='logout'))return;e.preventDefault();b.disabled=true;try{if(b.dataset.selectBankAccount)await selectBankAccount(b.dataset.selectBankAccount);else if(b.dataset.renewBank)await connectBank(b.dataset.renewBank);else{await api('/logout','POST',{});for(const key of ['invoices','transactions','allocations','suggestions','documents','imports','audit'])state[key]=[];state.dashboard={};state.settings={};state.bank={configured:false,connections:[]};state.gmail={configured:false,status:'disconnected'};state.loaded=null;showLogin();}}catch(err){handleError(err);}finally{if(b.isConnected)b.disabled=false;}});
app.addEventListener('submit',async e=>{if(e.target.id==='settings-form'){e.preventDefault();const f=new FormData(e.target),button=e.submitter;button.disabled=true;try{const body=Object.fromEntries(['company_name','organization_number','email','phone','address','bankgiro'].map(k=>[k,f.get(k)]));Object.assign(body,{sync_interval_minutes:Number(f.get('sync_interval_minutes')),notifications_due:f.has('notifications_due'),notifications_review:f.has('notifications_review')});await api('/settings','PATCH',body);await refresh();toast('Inställningarna har sparats.');}catch(err){document.querySelector('#settings-error').textContent=err.message;}finally{if(button.isConnected)button.disabled=false;}}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,a[data-nav]');if(!b||b.disabled)return;if(b.dataset.nav){e.preventDefault();navigate(b.dataset.nav,b.dataset.filter);return;}const jobs={'new-invoice':()=>invoiceDialog(),'new-transaction':bankDialog,'upload-invoice':uploadInvoice,'bank-file':bankFilePicker,'connect-bank':connectBank,gmail:gmailAction,'gmail-settings':gmailSettings,'disconnect-gmail':()=>disconnectDialog('gmail'),notifications,refresh:async()=>{await refresh();toast('Översikten har uppdaterats.');},menu:toggleMenu,'review-next':()=>{const t=state.transactions.find(t=>t.status==='suggested')||state.transactions.find(t=>t.available_cents>0&&!t.excluded);if(t)transactionDialog(t.id);else toast('Det finns inga bankhändelser att granska.');},'confirm-import':commitImport,'cancel-preview':()=>{state.preview=null;render();},'dismissed-documents':dismissedDocuments,'import-history':()=>modal('Importhistorik',importTable(state.imports),null,null,true),'export-invoices':exportInvoices,'export-all':exportAll,'download-reminder':()=>download('betalningspaminnelse-utkast.txt',document.querySelector('#reminder-text').value)};try{if(b.dataset.action&&jobs[b.dataset.action]){b.disabled=true;try{await jobs[b.dataset.action]();}finally{if(b.isConnected)b.disabled=false;}}else if(b.dataset.invoice)await invoiceDetail(b.dataset.invoice);else if(b.dataset.transaction)transactionDialog(b.dataset.transaction);else if(b.dataset.restoreDocument){await api('/documents','PATCH',{id:b.dataset.restoreDocument,status:'needs_review',reason:'Återställd för ny granskning'});closeModal();await refresh();toast('Underlaget kan granskas igen.');}else if(b.dataset.dismissDocument)dismissDocument(b.dataset.dismissDocument);else if(b.dataset.document)invoiceDialog(state.documents.find(d=>d.id===b.dataset.document));else if(b.dataset.editInvoice)invoiceDialog(null,state.invoices.find(i=>i.id===b.dataset.editInvoice));else if(b.dataset.reconcile)reconcileDialog(b.dataset.reconcile);else if(b.dataset.reminder)reminderDialog(b.dataset.reminder);else if(b.dataset.attach)uploadInvoice(b.dataset.attach);else if(b.dataset.undo)undoDialog(b.dataset.undo);else if(b.dataset.exclude)excludeDialog(b.dataset.exclude);else if(b.dataset.restore){await api('/bank-transactions','PATCH',{id:b.dataset.restore,excluded:false});closeModal();await refresh();toast('Bankhändelsen kan granskas igen.');}else if(b.dataset.import)importDetail(b.dataset.import);else if(b.dataset.sync){b.disabled=true;try{await syncBank(b.dataset.sync);}finally{if(b.isConnected)b.disabled=false;}}else if(b.dataset.disconnectBank)disconnectDialog('bank',b.dataset.disconnectBank);else if(b.dataset.bankFilter){state.filters.bank.status=b.dataset.bankFilter;state.filters.bank.page=1;render();}else if(b.dataset.page){state.filters[state.tab].page=Number(b.dataset.page);rerenderResults();}else if(b.dataset.sort){const f=state.filters[state.tab];f.asc=f.sort===b.dataset.sort?!f.asc:true;f.sort=b.dataset.sort;rerenderResults();}}catch(err){handleError(err);}});
app.addEventListener('input',e=>{if(e.target.dataset.search){const f=state.filters[e.target.dataset.search];f.q=e.target.value;f.page=1;rerenderResults();}});
app.addEventListener('change',e=>{if(e.target.dataset.filterSelect){state.filters[state.tab][e.target.dataset.filterSelect]=e.target.value;state.filters[state.tab].page=1;rerenderResults();}if(e.target.hasAttribute('data-page-size')){state.filters[state.tab].size=Number(e.target.value);state.filters[state.tab].page=1;rerenderResults();}});
app.addEventListener('dragover',e=>{const card=e.target.closest('[data-drop]');if(card){e.preventDefault();card.classList.add('dragging');}});
app.addEventListener('dragleave',e=>{const card=e.target.closest('[data-drop]');if(card&&!card.contains(e.relatedTarget))card.classList.remove('dragging');});
app.addEventListener('drop',e=>{const card=e.target.closest('[data-drop]');if(!card)return;e.preventDefault();card.classList.remove('dragging');const files=[...e.dataTransfer.files];if(!files.length)return;(card.dataset.drop==='bank'?previewFile(files[0]):uploadInvoices(files)).catch(handleError);});
refresh().then(loaded=>{if(!loaded)return;const q=new URLSearchParams(location.search),bankStatus=q.get('status');if(bankStatus==='select_account'&&state.bank.connections.some(c=>c.status==='pending_account'))toast('Bankens godkännande är klart. Välj företagets konto för att slutföra anslutningen.');else if(bankStatus==='connected'&&bankConnected())toast('Bankkontot är anslutet. Granska dina bankhändelser under Bank.');if(q.get('gmail')==='connected'&&gmailConnected())toast('Gmail är ansluten. Du kan nu hämta fakturaunderlag.');if(bankStatus==='cancelled'||q.get('gmail')==='cancelled')toast('Anslutningen avbröts. Du kan koppla igen när du vill.');if(bankStatus==='error')toast('Bankanslutningen kunde inte slutföras. Försök koppla banken igen.',true);if(q.has('status')||q.has('gmail'))history.replaceState(null,'',state.tab==='overview'?'/':'/?tab='+encodeURIComponent(state.tab));}).catch(err=>{if(err.status===401){showLogin();return;}app.innerHTML=`<main class="loading-screen"><div class="fatal-error"><h1>Det gick inte att öppna fakturakollen</h1><p>${esc(err.message)}</p><button class="primary" id="retry">Försök igen</button></div></main>`;document.querySelector('#retry').onclick=()=>location.reload();});
